  background_removal_task?: "remove_simple_background" | "remove_complex_background";
  // Where the source canvas sits inside context_image: width/height must equal the source size, and the box must lie entirely within the context image.
  bounding_box?: { height: number; width: number; x: number; y: number; } | null;
