  usage_description?: string | null;
} | null;
  crop_to_mask?: true;
  description: string;
  image_base64?: string | null;
  image_url?: string | null;
  mask_height?: number | null;
  // Mask PNG, exactly the source size. EVERY pixel's RGB must be pure white (generate) or pure black (keep): a grey or coloured pixel is refused, so remove any antialiasing, and a mask with no white at all is refused too. The mask's own alpha is ignored. Unlike inpaint_image, which does not check this, Pro Flash enforces it. Or give the four mask_x/y/width/height instead.
  mask_image_base64?: string | null;
  // Same mask as mask_image_base64, from an https, data: or `upload:<id>` URL.
  mask_image_url?: string | null;
  mask_width?: number | null;
  mask_x?: number | null;
  mask_y?: number | null;
  // Background removal on the GENERATED pixels. Left out it follows the source: on if the source has any non-opaque pixel, off if it is fully opaque. Removal runs before the frozen pixels are copied back, so masked pixels CAN come back transparent (how a bigger hairstyle keeps gaps around it) and pixels outside the mask are untouched either way. Off, the render is drawn on a background, so the masked area comes back opaque.
  no_background?: boolean | null;
  // What comes back, always at the source's own size. `Modify current layer` (default) is the whole sprite with the mask area replaced. `Modify current layer, only changes` and `New layer with changes` are that same canvas holding ONLY the masked pixels, fully transparent everywhere else - a layer to drop over your own art. Every pixel outside the mask is copied from your source byte for byte, and that copy is the LAST step, after background removal and palette work, so nothing outside the mask can shift.
  output_method?: "New layer with changes" | "Modify current layer, only changes" | "Modify current layer";
  project_id?: string | null;
  seed?: number;
  source_image_id?: string | null;
}): Promise<CallToolResult>; };
